import * as zlib from 'zlib';
import { promisify } from 'util';

const inflate = promisify(zlib.inflate);
const deflate = promisify(zlib.deflate);

interface TenantConfig {
  tenantId: string;
  maxPayloadBytes: number;
  maxDecompressedBytes: number;
  allowNestedSerialization: boolean;
}

interface SerializedEnvelope {
  version: number;
  tenantId: string;
  compression: 'none' | 'zlib';
  layers: number;
  checksum: number;
  payload: string;
}

const TENANT_CONFIGS: Map<string, TenantConfig> = new Map([
  ['tenant-a', { tenantId: 'tenant-a', maxPayloadBytes: 1024 * 1024, maxDecompressedBytes: 10 * 1024 * 1024, allowNestedSerialization: true }],
  ['tenant-b', { tenantId: 'tenant-b', maxPayloadBytes: 512 * 1024, maxDecompressedBytes: 5 * 1024 * 1024, allowNestedSerialization: false }],
]);

function computeChecksum(data: Buffer): number {
  let hash = 0;
  for (let i = 0; i < data.length; i++) {
    hash = ((hash << 5) - hash + data[i]) | 0;
  }
  return hash >>> 0;
}

function validateTenantIsolation(envelope: SerializedEnvelope, requestTenantId: string): boolean {
  if (envelope.tenantId !== requestTenantId) {
    throw new Error(`Tenant isolation violation: ${envelope.tenantId} !== ${requestTenantId}`);
  }
  return true;
}

async function decompressLayer(compressed: Buffer, config: TenantConfig, currentDepth: number, totalDecompressed: { bytes: number }): Promise<Buffer> {
  // Enforce max compressed input size
  if (compressed.length > config.maxPayloadBytes) {
    throw new Error(`Compressed payload exceeds limit: ${compressed.length} > ${config.maxPayloadBytes}`);
  }

  const decompressed = await inflate(compressed);

  // Track cumulative decompressed bytes across ALL layers
  totalDecompressed.bytes += decompressed.length;

  // Check CUMULATIVE decompressed size against tenant limit
  if (totalDecompressed.bytes > config.maxDecompressedBytes) {
    throw new Error(`Cumulative decompressed size exceeds tenant limit: ${totalDecompressed.bytes} > ${config.maxDecompressedBytes}`);
  }

  return decompressed;
}

async function deserializeEnvelope(raw: Buffer, requestTenantId: string): Promise<any> {
  const config = TENANT_CONFIGS.get(requestTenantId);
  if (!config) {
    throw new Error(`Unknown tenant: ${requestTenantId}`);
  }

  // Parse outer envelope
  const envelopeStr = raw.toString('utf-8');
  const envelope: SerializedEnvelope = JSON.parse(envelopeStr);

  validateTenantIsolation(envelope, requestTenantId);

  if (envelope.version !== 2) {
    throw new Error(`Unsupported version: ${envelope.version}`);
  }

  // Hard cap on layers regardless of envelope claim
  const MAX_ALLOWED_LAYERS = 3;

  let payloadBuffer = Buffer.from(envelope.payload, 'base64');

  // Verify checksum of compressed payload
  const expectedChecksum = computeChecksum(payloadBuffer);
  if (expectedChecksum !== envelope.checksum) {
    throw new Error('Checksum mismatch');
  }

  if (envelope.compression === 'zlib') {
    // Process nested compression layers with hard cap
    const maxLayers = config.allowNestedSerialization ? Math.min(envelope.layers, MAX_ALLOWED_LAYERS) : 1;
    const totalDecompressed = { bytes: 0 };

    for (let depth = 0; depth < maxLayers; depth++) {
      payloadBuffer = await decompressLayer(payloadBuffer, config, depth, totalDecompressed);

      // After first decompression, check if result is another compressed layer
      // by looking for zlib magic bytes (0x78)
      if (depth < maxLayers - 1 && payloadBuffer[0] === 0x78) {
        // Continue decompression - cumulative tracking prevents bomb
        continue;
      } else {
        break;
      }
    }
  }

  return JSON.parse(payloadBuffer.toString('utf-8'));
}

async function serializeForTenant(data: any, tenantId: string, layers: number = 1): Promise<Buffer> {
  const config = TENANT_CONFIGS.get(tenantId);
  if (!config) {
    throw new Error(`Unknown tenant: ${tenantId}`);
  }

  let payload = Buffer.from(JSON.stringify(data), 'utf-8');

  const actualLayers = config.allowNestedSerialization ? Math.min(layers, 3) : 1;

  for (let i = 0; i < actualLayers; i++) {
    payload = await deflate(payload);
  }

  const checksum = computeChecksum(payload);

  const envelope: SerializedEnvelope = {
    version: 2,
    tenantId,
    compression: 'zlib',
    layers: actualLayers,
    checksum,
    payload: payload.toString('base64'),
  };

  return Buffer.from(JSON.stringify(envelope), 'utf-8');
}

// Request handler
export async function handleDeserializeRequest(
  rawBody: Buffer,
  tenantIdFromAuth: string
): Promise<{ success: boolean; data?: any; error?: string }> {
  try {
    // Validate raw body size (pre-parse check)
    const config = TENANT_CONFIGS.get(tenantIdFromAuth);
    if (!config) {
      return { success: false, error: 'Unknown tenant' };
    }

    if (rawBody.length > config.maxPayloadBytes) {
      return { success: false, error: 'Request body too large' };
    }

    const result = await deserializeEnvelope(rawBody, tenantIdFromAuth);
    return { success: true, data: result };
  } catch (err: any) {
    return { success: false, error: err.message };
  }
}

export { serializeForTenant, deserializeEnvelope, TENANT_CONFIGS };
